def archive_workspace_root(base_name="/tmp/openclaw_workspace_archive", format="zip"):
    """Create an archive of the OpenClaw workspace root.

    Returns the path to the created archive.
    """
    return shutil.make_archive(
        base_name=str(base_name),
        format=format,
        root_dir=str(WORKSPACE_ROOT),
    )


